     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string', 'int_cast']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    36→        // 탑레벨 문장은 V 모드(C)로 처리
    37→        this.genVStatement(fnItem as AST.Statement);
    38→      }
    39→    }
    40→
    41→    const c = this.cLines.join('\n');
    42→    const python = this.pyLines.join('\n');
    43→
    44→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    45→    const mixed =
    46→      c && python
    47→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    48→        : c || python;
    49→
    50→    return { c, python, mixed };
    51→  }
    52→
    53→  /**
    54→   * 실행 가능한 프로그램 생성
    55→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    56→   */
    57→  generateProgram(program: AST.Program): CodegenResult {
    58→    const base = this.generate(program);
    59→
    60→    // C 코드에 헤더 + main() wrapping 추가
    61→    const cWithMain = base.c
    62→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    63→      : '';
    64→
    65→    // Python 코드에 main 블록 추가
    66→    const pyWithMain = base.python
    67→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    68→      : '';
    69→
    70→    return {
    71→      c: cWithMain,
    72→      python: pyWithMain,
    73→      mixed: base.mixed,
    74→    };
    75→  }
    76→
    77→  /**
    78→   * V 함수 → C 함수
    79→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    80→   * →
    81→   * long long add(long long x, long long y) { return x + y; }
    82→   */
    83→  private genVFunction(fn: AST.VFunction): void {
    84→    // 반환타입
    85→    const returnType = this.mapVType(fn.returnType || 'void');
    86→
    87→    // 파라미터 리스트
    88→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    89→
    90→    // 함수 시그니처
    91→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    92→
    93→    // 함수 본문
    94→    this.indentLevel++;
    95→    for (const stmt of fn.body) {
    96→      this.genVStatement(stmt);
    97→    }
    98→    this.indentLevel--;
    99→
   100→    this.writeC('}');
   101→    this.writeC(''); // 빈 줄
   102→  }
   103→
   104→  /**
   105→   * Python 함수 → Python 함수
   106→   * def slow(items): return items
   107→   * →
   108→   * def slow(items):
   109→   *     return items
   110→   */
   111→  private genPyFunction(fn: AST.PyFunction): void {
   112→    // 파라미터 리스트
   113→    const paramList = fn.params.map((p) => p.name).join(', ');
   114→
   115→    // 함수 정의
   116→    this.writePy(`def ${fn.name}(${paramList}):`);
   117→
   118→    // 함수 본문 (들여쓰기 필요)
   119→    this.indentLevel++;
   120→    for (const stmt of fn.body) {
   121→      this.genPyStatement(stmt);
   122→    }
   123→    this.indentLevel--;
   124→
   125→    this.writePy(''); // 빈 줄
   126→  }
   127→
   128→  /**
   129→   * V 문장 생성 (C 코드용)
   130→   */
   131→  private genVStatement(stmt: AST.Statement): void {
   132→    const s = stmt as any;
   133→
   134→    if (s.type === 'Return') {
   135→      const returnStmt = s as AST.ReturnStatement;
   136→      if (returnStmt.value) {
   137→        const expr = this.genVExpression(returnStmt.value);
   138→        this.writeC(`${this.indent()}return ${expr};`);
   139→      } else {
   140→        this.writeC(`${this.indent()}return;`);
   141→      }
   142→    } else if (s.type === 'Assign') {
   143→      const assignStmt = s as AST.AssignStatement;
   144→      const expr = this.genVExpression(assignStmt.value);
   145→      // 값의 타입에 따라 C 타입 결정
   146→      const value = assignStmt.value as any;
   147→      let cType = 'long long'; // 기본값
   148→      if (value.type === 'String') {
   149→        cType = 'char*'; // 문자열 리터럴
   150→      }
   151→      this.writeC(`${this.indent()}${cType} ${assignStmt.name} = ${expr};`);
   152→    } else if (s.type === 'ExprStatement') {
   153→      const exprStmt = s as AST.ExprStatement;
   154→      const expr = this.genVExpression(exprStmt.expression);
   155→      this.writeC(`${this.indent()}${expr};`);
   156→    } else if (s.type === 'IfStatement') {
   157→      const ifStmt = s as AST.IfStatement;
   158→      const cond = this.genVExpression(ifStmt.condition);
   159→      this.writeC(`${this.indent()}if (${cond}) {`);
   160→      this.indentLevel++;
   161→      for (const stmt of ifStmt.thenBranch) {
   162→        this.genVStatement(stmt);
   163→      }
   164→      this.indentLevel--;
   165→      this.writeC(`${this.indent()}}`);
   166→      if (ifStmt.elseBranch) {
   167→        this.writeC(`${this.indent()}else {`);
   168→        this.indentLevel++;
   169→        for (const stmt of ifStmt.elseBranch) {
   170→          this.genVStatement(stmt);
   171→        }
   172→        this.indentLevel--;
   173→        this.writeC(`${this.indent()}}`);
   174→      }
   175→    }
   176→  }
   177→
   178→  /**
   179→   * Python 문장 생성 (Python 코드용)
   180→   */
   181→  private genPyStatement(stmt: AST.Statement): void {
   182→    const s = stmt as any;
   183→    const indentStr = this.indent();
   184→
   185→    if (s.type === 'Return') {
   186→      const returnStmt = s as AST.ReturnStatement;
   187→      if (returnStmt.value) {
   188→        const expr = this.genPyExpression(returnStmt.value);
   189→        this.writePy(`${indentStr}return ${expr}`);
   190→      } else {
   191→        this.writePy(`${indentStr}return`);
   192→      }
   193→    } else if (s.type === 'Assign') {
   194→      const assignStmt = s as AST.AssignStatement;
   195→      const expr = this.genPyExpression(assignStmt.value);
   196→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   197→    } else if (s.type === 'ExprStatement') {
   198→      const exprStmt = s as AST.ExprStatement;
   199→      const expr = this.genPyExpression(exprStmt.expression);
   200→      this.writePy(`${indentStr}${expr}`);
   201→    }
   202→  }
   203→
   204→  /**
   205→   * V 표현식 생성 (C 코드용)
   206→   */
   207→  private genVExpression(expr: AST.Expression): string {
   208→    const e = expr as any;
   209→
   210→    if (e.type === 'Number') {
   211→      return (e as AST.NumberLiteral).value.toString();
   212→    }
   213→
   214→    if (e.type === 'String') {
   215→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   216→      return (e as AST.StringLiteral).value;
   217→    }
   218→
   219→    if (e.type === 'Identifier') {
   220→      return (e as AST.Identifier).name;
   221→    }
   222→
   223→    if (e.type === 'BinaryExpr') {
   224→      const binExpr = e as AST.BinaryExpr;
   225→      const left = this.genVExpression(binExpr.left);
   226→      const right = this.genVExpression(binExpr.right);
   227→      return `${left} ${binExpr.operator} ${right}`;
   228→    }
   229→
   230→    if (e.type === 'Call') {
   231→      const callExpr = e as AST.CallExpr;
   232→
   233→      // callee가 Identifier인 경우 함수명 추출
   234→      let calleeStr: string | null = null;
   235→      if (typeof callExpr.callee === 'string') {
   236→        calleeStr = callExpr.callee;
   237→      } else {
   238→        const calleeExpr = callExpr.callee as any;
   239→        if (calleeExpr.type === 'Identifier') {
   240→          calleeStr = calleeExpr.name;
   241→        }
   242→      }
   243→
   244→      // V 내장 함수 처리
   245→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   246→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   247→      }
   248→
   249→      // 일반 함수 호출
   250→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   251→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   252→      return `${callee}(${args})`;
   253→    }
   254→
   255→    return '';
   256→  }
   257→
   258→  /**
   259→   * V 모드 내장 함수 호출 생성
   260→   */
   261→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   262→    if (name === 'println') {
   263→      if (args.length === 0) return 'printf("\\n")';
   264→      const firstArg = args[0] as any;
   265→      // StringLiteral인 경우: printf의 format string으로 사용
   266→      if (firstArg.type === 'String') {
   267→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   268→        const str = firstArg.value.slice(1, -1);
   269→        return `printf("${str}\\n")`;
   270→      }
   271→      // 숫자/식별자인 경우 %lld 포맷 사용
   272→      const arg = this.genVExpression(firstArg);
   273→      return `printf("%lld\\n", ${arg})`;
   274→    }
   275→
   276→    if (name === 'print') {
   277→      if (args.length === 0) return 'printf("")';
   278→      const firstArg = args[0] as any;
   279→      if (firstArg.type === 'String') {
   280→        // StringLiteral인 경우: printf의 format string으로 사용
   281→        const str = firstArg.value.slice(1, -1);
   282→        return `printf("${str}")`;
   283→      }
   284→      const arg = this.genVExpression(firstArg);
   285→      return `printf("%lld", ${arg})`;
   286→    }
   287→
   288→    if (name === 'len') {
   289→      const firstArg = args[0] as any;
   290→      if (firstArg.type === 'String') {
   291→        // StringLiteral인 경우 따옴표 제거
   292→        const str = firstArg.value.slice(1, -1);
   293→        return `strlen("${str}")`;
   294→      }
   295→      const arg = this.genVExpression(firstArg);
   296→      return `strlen(${arg})`;
   297→    }
   298→
   299→    if (name === 'to_string') {
   300→      const arg = this.genVExpression(args[0]);
   301→      return arg; // 단순 pass-through
   302→    }
   303→
   304→    if (name === 'int_cast') {
   305→      const firstArg = args[0] as any;
   306→      if (firstArg.type === 'String') {
   307→        const str = firstArg.value.slice(1, -1);
   308→        return `atoi("${str}")`;
   309→      }
   310→      const arg = this.genVExpression(firstArg);
   311→      return `atoi(${arg})`;
   312→    }
   313→
   314→    return '';
   315→  }
   316→
   317→  /**
   318→   * Python 표현식 생성 (Python 코드용)
   319→   */
   320→  private genPyExpression(expr: AST.Expression): string {
   321→    const e = expr as any;
   322→
   323→    if (e.type === 'Number') {
   324→      return (e as AST.NumberLiteral).value.toString();
   325→    }
   326→
   327→    if (e.type === 'String') {
   328→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   329→      return (e as AST.StringLiteral).value;
   330→    }
   331→
   332→    if (e.type === 'Identifier') {
   333→      return (e as AST.Identifier).name;
   334→    }
   335→
   336→    if (e.type === 'BinaryExpr') {
   337→      const binExpr = e as AST.BinaryExpr;
   338→      const left = this.genPyExpression(binExpr.left);
   339→      const right = this.genPyExpression(binExpr.right);
   340→      return `${left} ${binExpr.operator} ${right}`;
   341→    }
   342→
   343→    if (e.type === 'Call') {
   344→      const callExpr = e as AST.CallExpr;
   345→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   346→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   347→      return `${callee}(${args})`;
   348→    }
   349→
   350→    return '';
   351→  }
   352→
   353→  /**
   354→   * V 타입 → C 타입 매핑
   355→   */
   356→  private mapVType(type: string): string {
   357→    const mapping: Record<string, string> = {
   358→      i64: 'long long',
   359→      i32: 'int',
   360→      f64: 'double',
   361→      f32: 'float',
   362→      bool: 'bool',
   363→      string: 'char*',
   364→      void: 'void',
   365→    };
   366→
   367→    return mapping[type] || type;
   368→  }
   369→
   370→  /**
   371→   * Python 타입 → Python 타입 (기본값)
   372→   */
   373→  private mapPyType(type: string): string {
   374→    const mapping: Record<string, string> = {
   375→      i64: 'int',
   376→      i32: 'int',
   377→      f64: 'float',
   378→      f32: 'float',
   379→      bool: 'bool',
   380→      string: 'str',
   381→      void: 'None',
   382→      int: 'int',
   383→      float: 'float',
   384→    };
   385→
   386→    return mapping[type] || type;
   387→  }
   388→
   389→  /**
   390→   * C 코드에 줄 추가
   391→   */
   392→  private writeC(line: string): void {
   393→    this.cLines.push(line);
   394→  }
   395→
   396→  /**
   397→   * Python 코드에 줄 추가
   398→   */
   399→  private writePy(line: string): void {
   400→    this.pyLines.push(line);
   401→  }
   402→
   403→  /**
   404→   * 현재 들여쓰기 문자열
   405→   */
   406→  private indent(): string {
   407→    return '    '.repeat(this.indentLevel);
   408→  }
   409→}
