     1→/**
     2→ * FreeLang Nexus Parser - 단위 테스트
     3→ */
     4→
     5→import NexusLexer from '../src/nexus/lexer/nexus-lexer';
     6→import { NexusParser } from '../src/nexus/parser/nexus-parser';
     7→import * as AST from '../src/nexus/parser/ast';
     8→
     9→describe('NexusParser - Phase 2 핵심 테스트', () => {
    10→  // ==================== Test 1: V 함수 기본 파싱 ====================
    11→  test('V 함수 기본: fn hello() {}', () => {
    12→    const source = `@mode(v)
    13→fn hello() {
    14→}`;
    15→    const lexer = new NexusLexer(source);
    16→    const tokens = lexer.tokenize();
    17→    const parser = new NexusParser(tokens);
    18→    const ast = parser.parse();
    19→
    20→    expect(ast.type).toBe('Program');
    21→    expect(ast.body.length).toBeGreaterThan(0);
    22→
    23→    const fn = ast.body[0] as AST.VFunction;
    24→    expect(fn.type).toBe('VFunction');
    25→    expect(fn.name).toBe('hello');
    26→    expect(fn.params.length).toBe(0);
    27→    expect(fn.body.length).toBe(0);
    28→    expect(fn.mode).toBe('v');
    29→  });
    30→
    31→  // ==================== Test 2: V 함수 + 파라미터 ====================
    32→  test('V 함수: fn add(x: i64, y: i64) -> i64 { return x + y }', () => {
    33→    const source = `@mode(v)
    34→fn add(x: i64, y: i64) -> i64 {
    35→  return x + y
    36→}`;
    37→    const lexer = new NexusLexer(source);
    38→    const tokens = lexer.tokenize();
    39→    const parser = new NexusParser(tokens);
    40→    const ast = parser.parse();
    41→
    42→    const fn = ast.body[0] as AST.VFunction;
    43→    expect(fn.name).toBe('add');
    44→    expect(fn.params.length).toBe(2);
    45→    expect(fn.params[0].name).toBe('x');
    46→    expect(fn.params[0].typeAnnotation).toBe('i64');
    47→    expect(fn.params[1].name).toBe('y');
    48→    expect(fn.params[1].typeAnnotation).toBe('i64');
    49→    expect(fn.returnType).toBe('i64');
    50→    expect(fn.body.length).toBeGreaterThan(0);
    51→
    52→    // Return 문장 확인
    53→    const returnStmt = fn.body[0] as AST.ReturnStatement;
    54→    expect(returnStmt.type).toBe('Return');
    55→    expect(returnStmt.value).toBeDefined();
    56→  });
    57→
    58→  // ==================== Test 3: Python 함수 기본 ====================
    59→  test('Python 함수 기본: def hello():', () => {
    60→    const source = `@mode(python)
    61→def hello():
    62→  pass`;
    63→    const lexer = new NexusLexer(source);
    64→    const tokens = lexer.tokenize();
    65→    const parser = new NexusParser(tokens);
    66→    const ast = parser.parse();
    67→
    68→    expect(ast.type).toBe('Program');
    69→    expect(ast.body.length).toBeGreaterThan(0);
    70→
    71→    const fn = ast.body[0] as AST.PyFunction;
    72→    expect(fn.type).toBe('PyFunction');
    73→    expect(fn.name).toBe('hello');
    74→    expect(fn.params.length).toBe(0);
    75→    expect(fn.mode).toBe('python');
    76→  });
    77→
    78→  // ==================== Test 4: Python 함수 + 본문 ====================
    79→  test('Python 함수: def add(a, b): return a + b', () => {
    80→    const source = `@mode(python)
    81→def add(a, b):
    82→  return a + b`;
    83→    const lexer = new NexusLexer(source);
    84→    const tokens = lexer.tokenize();
    85→    const parser = new NexusParser(tokens);
    86→    const ast = parser.parse();
    87→
    88→    const fn = ast.body[0] as AST.PyFunction;
    89→    expect(fn.name).toBe('add');
    90→    expect(fn.params.length).toBe(2);
    91→    expect(fn.params[0].name).toBe('a');
    92→    expect(fn.params[1].name).toBe('b');
    93→    expect(fn.body.length).toBeGreaterThan(0);
    94→
    95→    // Return 문장 확인
    96→    const returnStmt = fn.body[0] as AST.ReturnStatement;
    97→    expect(returnStmt.type).toBe('Return');
    98→  });
    99→
   100→  // ==================== Test 5: 혼합 파싱 ====================
   101→  test('혼합 모드: V 함수 + Python 함수 공존', () => {
   102→    const source = `@mode(v)
   103→fn fast(x: i64) -> i64 {
   104→  return x * x
   105→}
   106→
   107→@mode(python)
   108→def slow(items):
   109→  return items`;
   110→    const lexer = new NexusLexer(source);
   111→    const tokens = lexer.tokenize();
   112→    const parser = new NexusParser(tokens);
   113→    const ast = parser.parse();
   114→
   115→    // V 함수 확인
   116→    let vCount = 0;
   117→    let pyCount = 0;
   118→
   119→    for (const item of ast.body) {
   120→      if ((item as any).type === 'VFunction') vCount++;
   121→      if ((item as any).type === 'PyFunction') pyCount++;
   122→    }
   123→
   124→    expect(vCount).toBeGreaterThan(0);
   125→    expect(pyCount).toBeGreaterThan(0);
   126→
